const agentItem = $input.first().json;
const strategy = agentItem.output || agentItem;

const analystArtifact = $('Validate Evidence Coverage').first().json.artifact;
const evidenceSet = $('Build Evidence Records').first().json.evidence || [];

const validIds = new Set(evidenceSet.map(e => e.evidence_id));

function collectAnalystIds(node) {
  if (node === null || node === undefined) return;
  if (Array.isArray(node)) { node.forEach(collectAnalystIds); return; }
  if (typeof node === 'object') {
    if (typeof node.theme_id === 'string') validIds.add(node.theme_id);
    if (typeof node.item_id === 'string') validIds.add(node.item_id);
    if (typeof node.id === 'string' && /^(ASM|UNK|CONF)-[0-9]+$/.test(node.id)) validIds.add(node.id);
    for (const key of Object.keys(node)) collectAnalystIds(node[key]);
  }
}
collectAnalystIds(analystArtifact);

const citedFields = [];

function isCitedFieldShape(node) {
  return node && typeof node === 'object' && !Array.isArray(node)
    && 'value' in node && 'supporting_ids' in node && 'basis' in node;
}

function walk(node, path) {
  if (node === null || node === undefined) return;
  if (Array.isArray(node)) { node.forEach((item, i) => walk(item, `${path}[${i}]`)); return; }
  if (typeof node === 'object') {
    if (isCitedFieldShape(node)) {
      citedFields.push({ path, value: node.value, supporting_ids: node.supporting_ids, basis: node.basis });
      return;
    }
    for (const key of Object.keys(node)) walk(node[key], path ? `${path}.${key}` : key);
  }
}

walk(strategy, '');

const basisCounts = { evidence: 0, brief_stated: 0, inference: 0, invalid: 0 };
const blendingViolations = [];
const unresolvedIds = [];

for (const field of citedFields) {
  const basis = field.basis;
  if (!['evidence', 'brief_stated', 'inference'].includes(basis)) {
    basisCounts.invalid++;
  } else {
    basisCounts[basis]++;
  }

  const ids = Array.isArray(field.supporting_ids) ? field.supporting_ids : [];

  if (basis === 'evidence' && ids.length === 0) {
    blendingViolations.push({
      path: field.path,
      reason: 'basis is "evidence" but supporting_ids is empty -- asserts sourced backing with no citation',
      value: field.value,
    });
  }

  for (const id of ids) {
    if (!validIds.has(id)) {
      unresolvedIds.push({ path: field.path, id, basis });
    }
  }
}

return [{
  json: {
    strategy,
    validation: {
      total_cited_fields: citedFields.length,
      basis_distribution: basisCounts,
      blending_violations: blendingViolations,
      unresolved_supporting_ids: unresolvedIds,
      clean: blendingViolations.length === 0 && unresolvedIds.length === 0,
    },
  },
}];

const stratItem = $input.first().json;
const strategy = stratItem.strategy;
const strategyValidation = stratItem.validation;

const analystValidation = $('Validate Evidence Coverage').first().json.validation;

const errors = [];

if (!strategyValidation || strategyValidation.clean !== true) {
  errors.push(`Strategy grounding is not clean: ${JSON.stringify(strategyValidation && {
    blending_violations: strategyValidation.blending_violations,
    unresolved_supporting_ids: strategyValidation.unresolved_supporting_ids,
  })}`);
}
if (!analystValidation || analystValidation.all_references_valid !== true) {
  errors.push('Upstream Analyst evidence coverage is not clean (all_references_valid is not true).');
}

const requiredKeys = [
  'brief_id', 'icps', 'pains_and_outcomes', 'value_proposition', 'positioning',
  'message_pillars', 'channels', 'launch_phases', 'success_metrics', 'risks',
  'follow_up_research_questions',
];

if (!strategy || typeof strategy !== 'object') {
  errors.push('Strategy artifact is missing or not an object.');
} else {
  for (const key of requiredKeys) {
    if (!(key in strategy)) errors.push(`Missing required field: ${key}`);
  }

  const checkArrayBounds = (key, min, max) => {
    const arr = strategy[key];
    if (!Array.isArray(arr)) { errors.push(`${key} is missing or not an array.`); return; }
    if (arr.length < min) errors.push(`${key} has ${arr.length} items, needs at least ${min}.`);
    if (max !== undefined && arr.length > max) errors.push(`${key} has ${arr.length} items, must not exceed ${max}.`);
  };
  checkArrayBounds('icps', 1, 3);
  checkArrayBounds('message_pillars', 3, 5);
  checkArrayBounds('pains_and_outcomes', 1);
  checkArrayBounds('channels', 1);
  checkArrayBounds('launch_phases', 1);
  checkArrayBounds('success_metrics', 1);
  checkArrayBounds('risks', 1);

  const vp = strategy.value_proposition;
  if (!vp || typeof vp !== 'object') {
    errors.push('value_proposition is missing or not an object.');
  } else {
    for (const field of ['no_bundle_gap_response', 'low_brand_recognition_response']) {
      const f = vp[field];
      if (!f || typeof f.value !== 'string' || f.value.trim().length === 0) {
        errors.push(`value_proposition.${field} is missing or empty.`);
      }
    }
  }
}

if (errors.length > 0) {
  throw new Error(`Rejected: content is incomplete or invalid for the Docs Writer step.\n- ${errors.join('\n- ')}`);
}

return [{
  json: {
    status: 'accepted',
    brief_id: strategy.brief_id,
    artifact: strategy,
    checks_passed: {
      strategy_grounding_clean: true,
      analyst_evidence_clean: true,
      required_fields_present: true,
      bounds_respected: true,
      brief_compliance_fields_present: true,
    },
  },
}];

const input = $input.first().json;

if (input.status !== 'accepted') {
  throw new Error('Docs Writer received an item that was not marked accepted by the validation gate -- refusing to proceed.');
}

const artifact = input.artifact;

// Placeholder for the real Docs Writer: Google Docs OAuth is deferred to P6.2
// (see SETUP_DECISIONS.md). This node's only job right now is to prove it never
// receives anything the gate upstream didn't explicitly accept -- it does not yet
// call any external API.
const summary = {
  brief_id: input.brief_id,
  sections_ready: [
    'Ideal customer profiles',
    'Customer pains and desired outcomes',
    'Value proposition',
    'Positioning and differentiation',
    'Message pillars',
    'Recommended channels',
    'Launch phases and activities',
    'Success metrics',
    'Risks',
    'Follow-up research questions',
  ],
  icp_count: artifact.icps.length,
  message_pillar_count: artifact.message_pillars.length,
  channel_count: artifact.channels.length,
};

return [{
  json: {
    docs_writer_status: 'placeholder -- Google Docs OAuth deferred to P6.2, see SETUP_DECISIONS.md',
    summary,
    artifact,
  },
}];
